/** Size keys generated by the CMS theme -> names used by the frontend. */
const SIZE_KEYS = { thumbnail: "thumb", "1:1": "square", "3:2": "standard", "16:9": "wide", hero: "hero" };

/**
 * Normalizes a CMS image (ACF-like object or plain URL). Returns null when there is no image,
 * so components can do `image && <Img />`.
 * @param {any} raw
 * @returns {{ url: string, alt: string, width: number | null, height: number | null, sizes: Record<string, { url: string, width: number | null, height: number | null }> } | null}
 */
export function mapImage(raw) {
	if (!raw) {
		return null;
	}
	if (typeof raw === "string") {
		return { url: raw, alt: "", width: null, height: null, sizes: {} };
	}
	if (!raw.url) {
		return null;
	}
	const sizes = {};
	for (const [key, name] of Object.entries(SIZE_KEYS)) {
		if (raw.sizes?.[key]) {
			sizes[name] = {
				url: raw.sizes[key],
				width: raw.sizes[`${key}-width`] ?? null,
				height: raw.sizes[`${key}-height`] ?? null,
			};
		}
	}
	return { url: raw.url, alt: raw.alt || raw.title || "", width: raw.width ?? null, height: raw.height ?? null, sizes };
}
